 const refreshRef=useRef(refresh);refreshRef.current=refresh;
 const sendRecheck=useRef<ReturnType<typeof createSendRecheck>|null>(null);
 if(!sendRecheck.current)sendRecheck.current=createSendRecheck({
  reconcile:target=>api.reconcile(target),
  isCurrent:context=>activeRoom.current===context.roomId&&sendIdentity.current.get(context.roomId)?.id===context.id,
  onChecking:()=>{setSendRechecking(true);setSendOutcome('');},
  onSettled:(verdict,context)=>{
   setSendRechecking(false);
   // Every verdict replaces the unknown banner with a send-specific conclusion line; drop only that
   // banner so a concurrent unrelated error is never clobbered (undetermined keeps its own retry entry).
   setError(previous=>previous===explain('upstream_operation_unknown')?'':previous);
   if(verdict==='delivered'){
    if(replyRef.current?.messageId===context.replyToMessageId)setReply(undefined);
    setDrafts(d=>d[context.roomId]===context.text?{...d,[context.roomId]:''}:d);
    if(sendIdentity.current.get(context.roomId)?.id===context.id)sendIdentity.current.delete(context.roomId);
    setSendOutcome('delivered');
    void refreshRef.current();
   }else if(verdict==='not_delivered'){
    setSendOutcome('not_delivered');
   }else{
    setSendOutcome('undetermined');
   }
  },
 });
 const open=async(type:string)=>{botCreation.current.abort();botCreation.current=new AbortController();setAgent(BUILTIN);setModal(type);setName('');setGoal('');setSelectedBots([]);requestId.current=crypto.randomUUID();if(type==='bot'){try{const catalog=await api.models();setModels(catalog.models);setModelId(catalog.defaultModelId);}catch(error){setError(explain(error));}}};
