 const sendAttachmentMessage=async(input:any)=>{let result;try{result=await api.sendAttachments(input);}catch(error){const view=await attachments.refresh(input.roomId),known=view?.sends?.find((item:any)=>item.id===input.id&&item.status==='complete');if(!known)throw error;result={ok:true,messageId:known.messageId};}attachments.consume(input.roomId,input.uploadIds);void attachments.refresh(input.roomId).catch(()=>{});return result;};
